    #[test]
    fn semantic_sources_do_not_redeclare_attribute_modifier_types() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/attribute_modifier_types.rs") {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if contains_numeric_attribute_modifier_operation_reference(&source) {
                    violations.push(format!(
                        "{}: numeric operation_id reference",
                        path.display()
                    ));
                }
                if contains_numeric_attribute_modifier_slot_or_display_reference(&source) {
                    violations.push(format!(
                        "{}: numeric attribute-modifier slot/display reference",
                        path.display()
                    ));
                }
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("fn decode_attribute_modifier_operation_id")
                    || production.contains("fn attribute_modifier_operation_id")
                    || production.contains(
                        "[\"add_value\", \"add_multiplied_base\", \"add_multiplied_total\"]",
                    )
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        let crates = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        for directory in [
            "bbb-native/src",
            "bbb-world/src",
            "bbb-net/src",
            "bbb-item-model/src",
            "bbb-renderer/src",
        ] {
            visit(&crates.join(directory), &mut violations);
        }
        assert!(
            violations.is_empty(),
            "parallel attribute modifier type owners: {violations:?}"
        );
    }

    #[test]
    fn item_model_custom_registry_fixture_uses_generated_operation_constants() {
        let source = include_str!("../../bbb-item-model/src/item_runtime/tests.rs");
        let fixture = source
            .split("let custom_attribute_id")
            .nth(1)
            .and_then(|source| source.split("let default_attribute_item").next())
            .expect("item-model custom attribute fixture");
        assert!(fixture.contains("VANILLA_ATTRIBUTE_MODIFIER_OPERATION_ADD_VALUE_ID"));
        assert!(fixture.contains("VANILLA_ATTRIBUTE_MODIFIER_OPERATION_ADD_MULTIPLIED_BASE_ID"));
        assert!(fixture.contains("custom_attribute_id(\"minecraft:attack_damage\")"));
        assert!(fixture.contains("custom_attribute_id(\"minecraft:scale\")"));
        assert!(!fixture.contains("operation_id, slot_id|"));
        assert!(!fixture.contains("attribute_id: 7"));
        assert!(!fixture.contains("modifier_with_attribute(0,"));
        assert!(!fixture.contains("modifier_with_attribute(1,"));
    }
